"""The one master list of steps.  BUILD 1 to 4 make the dark box, 5 to 10 the front plate.  A step is named by its section and number (BUILD 7, FILM IN 2):
the printed guide, the clips and the web pages all use that name.
  The kit booklet prints 'do' and 'check'; the build manual prints everything.
Change a step here and both documents change."""
S = lambda sec, n, img, do, check, ifnot="", why="", parts=(), bursts=(): dict(sec=sec, n=n, img=img, do=do, check=check, ifnot=ifnot, why=why, parts=list(parts), bursts=list(bursts))
STEPS = [
 S('BUILD', 1, 'b6', 'Slide the spool, big red knob up, into the round chamber on the right (seen from behind).', 'The big red knob sits on top of the camera and turns.', "Its plain end goes into the slot in the floor, the knob's neck into the slot in the roof.", 'The spool, its shaft and its knob are one piece, because this is the part you turn hardest. A collar on its neck rides in a pocket inside the roof: when the back is on, the knob cannot come out.', [('body', 1), ('spool', 1)]),
 S('BUILD', 2, 'b7', 'Slide the small green knob into the slot on the left.', 'It turns. It only comes out backwards.', '', "This knob will turn the film's own spool. Its forked end fits over a bar inside the film.", [('knob', 1)]),
 S('BUILD', 3, 'b8', 'Lay the back down, inside up. Hold the blue frame wheel with its dial just past the edge of the back. Lay its neck in the fork, then slide it toward the long round post until its teeth touch the end of the post.', 'The wheel turns freely. It does not lift out of the fork.', 'If it lifts out, it was not slid home: slide it 3 mm toward the edge, press it down into the fork, slide it back.', "The film will turn this wheel: its eight teeth sit in the holes along the film's top edge, and one turn of the dial is one picture. Below the wheel, the film slides round the post.", [('back', 1), ('roller', 1)]),
 S('BUILD', 4, 'b9', 'Press the back on until both ends click.', 'Two clicks. The back does not pull off. Pinch the two pads and it does.', 'If it will not close, the frame wheel is not slid home or a knob is not fully in.', 'A nub on a springy finger at each end comes up behind a bar on the body. A ridge all round the back sits in a groove: that keeps the light out. This is the dark box. Everything else goes on its front.', [], [(0.1, 0.8, 'CLICK'), (0.3, 0.1, 'CLICK')]),
 S('BUILD', 5, 'b1', 'Lay the front plate face down. Drop the shutter onto the round peg near the top edge, with its rocker (the bar across its top) hanging over the edge.', 'The rocker sits just outside the edge. The shutter swings and clicks.', 'If it will not lie flat, it is upside down: the rocker must stand up toward you.', "The peg is the shutter's pivot. The shutter's own rim is its spring: a tooth on the rim drops into three notches in the edge of the pocket it lies in.", [('front', 1), ('blade', 1)]),
 S('BUILD', 6, 'b2', 'Pick the plate up and hold it flat. Drop the wheel onto the other peg, handle down through the curved slot.', 'The handle sticks out of the front. The wheel clicks into three places.', 'If the wheel will not lie flat, its handle is not in the slot.', 'The wheel carries three holes of different sizes. Its rim is a spring too.', [('wheel', 1)]),
 S('BUILD', 7, 'b3', "Keep the plate flat. Lower the camera onto it, front down, a little high and a little to one side, until its four pockets drop over the plate's four feet.", 'The camera lies flat on the plate. Nothing rocks.', 'If it rocks, move it about a few millimetres. The feet drop in at one place only.', 'Each foot has a hook underneath and a lip on one side. Each pocket is open at one corner only: that is the way in, and the only way out.'),
 S('BUILD', 8, 'b3b', 'Pinch camera and plate together and turn them over. Slide the plate sideways until it stops.', "The point on the plate's top edge is in line with the middle line on top of the camera.", 'If it will not slide, it is not flat on the camera: go back one step.', "Now the lips on the feet are under the camera's skin. The plate can no longer be lifted off."),
 S('BUILD', 9, 'b3c', 'Slide the plate down until it clicks.', 'One click. Its top edge is level with the top of the camera.', 'If there is no click, press the plate flat against the body while you slide.', 'The hooks are home and a springy tongue has dropped behind a bump. To come off, the plate has to go up past the click, then sideways, then away: a knock cannot do all three.', [], [(0.16, 0.42, 'CLICK')]),
 S('BUILD', 10, 'b4', 'Press the lens into the round pocket on the front, bulge outward, until it stops. (No lens? The pinhole ring goes here instead.)', 'It sits level and stays in when you shake the camera.', 'If it is loose or will not go in, tell whoever made the kit: the pocket is made for one size of lens.', 'Three small ribs in the pocket squeeze the lens. Nothing else in the camera is held by a squeeze.', [('lens', 1)]),
 S('FILM IN', 1, 'l1', 'Pinch the two pads, top and bottom. Lift the back off.', 'The frame wheel comes away with the back.', '', 'Do this in the shade, never in bright sun.'),
 S('FILM IN', 2, 'l2', 'Slide the small green knob out. Push its forked end into the hollow end of the film.', 'Turning the knob turns the spool inside the film.', 'Wrong end? The other end of the film has a peg sticking out.', "The fork straddles a bar inside the film's spool.", [('knob', 1), ('cassette', 1)]),
 S('FILM IN', 3, 'l3', "Slide film and knob in together on the left, the film's lip pointing to the middle.", 'The film sits flat in its chamber.', '', ''),
 S('FILM IN', 4, 'l4', 'Turn the big red knob until the slot in its spool faces you. Pull the film across and tuck its tip into the slot. Give the big red knob one turn.', 'The film is caught. It lies over the two curved rails.', 'If the tip slips out, tuck it deeper and turn again.', 'The film lies on a curve around the lens. That curve is why one simple lens can be sharp from corner to corner.'),
 S('FILM IN', 5, 'l5', 'Close the back.', 'Two clicks. Keep it shut until the film is out.', '', "The frame wheel's teeth press on the film's top edge. If they are not in the holes yet, the first turn of the knob drops them in.", [], [(0.1, 0.8, 'CLICK'), (0.3, 0.1, 'CLICK')]),
 S('FILM IN', 6, 'l6', 'Turn the big red knob the way the picture shows until it stops: about 25 turns for a film of 24 pictures, about 33 for 36. Then leave it alone.', 'While you turn, the arrow on the blue dial goes round and round: the film is moving.', 'If the arrow does not move, open the back in the shade and tuck the film in again. When the knob stops, stop: never force it.', "The knob's teeth lean one way: your fingers catch when you turn it the right way and slip the other way. You have wound the whole film out of its shell. Every picture you take will be wound back into the shell, where light cannot reach it."),
 S('PHOTOS', 1, 's1', 'Slide the handle on the front to a dot. The chart shows which one, for your film and the light.', 'It clicks at each dot.', '', 'The dot shows the size of the hole behind it. Each dot lets in about twice the light of the one before. When even the largest is too small for a snap, take a time picture.'),
 S('PHOTOS', 2, 's2', 'Aim along the middle line on top: from the edge of the pad at the back to the point at the front. The picture fits between the two outer lines.', 'Stand at least two big steps away from what you are photographing.', '', 'Nearer than that and the picture is not sharp: the focus is fixed.'),
 S('PHOTOS', 3, 's3', 'Hold still. Press the raised side of the rocker flat, in one quick press.', 'One click. Now the other side is up: that is the side to press next time.', 'If the rocker stops level, the shutter is open: press it on down. (That picture will be too bright.)', 'A window in the shutter passes the hole as it swings. A quick press lets light in for about one three-hundredth of a second. A slow press lets in more.', [], [(0.62, 0.93, 'CLICK')]),
 S('PHOTOS', 4, 's4', 'Turn the small green knob the way the picture shows until the arrow on the blue dial has gone once round. Keep your other hand off the big red knob.', 'The arrow points at its mark on the body again.', 'If the knob is stiff, stop and take your hand off the big red knob. Never force it.', "One turn of the dial is one picture's length of film, wound back into the shell."),
 S('FILM OUT', 1, 's4', 'After the last picture, keep turning the small green knob until the arrow on the dial stops moving. Then three more turns.', 'The arrow no longer moves: all the film is back in its shell.', '', ''),
 S('FILM OUT', 2, 'u1', 'Open the back. Slide the film out with its knob and pull the knob off. Send it off with your developing card, or take it to any photo lab.', "The film's tip is inside the shell, or just peeping out.", '', 'Any lab that develops 35 mm film can do it.'),
]
# The pinhole experiment (lesson 1): a picture without the lens.  One front plate does both: the lens comes out, and the pinhole disc goes in its pocket, held by the pinhole ring.
# The kit's disc is laser-drilled; a disc made at home is a piece of drinks can and a pin.  In the printed guide (page 15) and on the website.
WEB = [
 S('THE HOLE', 1, 'p_pindisc', 'Take the pinhole disc from the bag, or make one. Ask an adult to cut a square about 10 mm across from a clean drinks can with kitchen scissors, and to snip off its four corners. Lay it on card, press a pin into the middle to make a dent, then push just until the tip comes through.', 'Hold it up to a lamp: one tiny round point of light, no tear.', 'A tear, or a hole you can see without the lamp: make another. The edges of can metal are sharp: hold it by its flat sides.', 'The best hole for this camera is a quarter of a millimetre across: only the very tip of a pin. Lesson 1 shows why. No heating, no knives: scissors, a pin and a piece of card.', [('pinring', 1), ('pindisc', 1)]),
 S('THE HOLE', 2, 'h2', 'Leave the lens out (or push it out from behind with the front plate off). Lay the disc flat in the round pocket, hole in the middle, and press the pinhole ring in on top of it until it stops.', 'The disc covers the hole in the floor of the pocket all round. The ring stands a little proud and does not wobble.', 'If the disc will not lie flat in the pocket, snip its corners a little more.', 'Same plate, same pocket: with the lens it is a lens camera; with the disc and ring it is a pinhole camera. To change back, lift the ring out with a fingernail and tip the disc out.'),
 S('THE HOLE', 3, 'h_hero', 'Set the large dot. Stand the camera on something steady. Hold the rocker level to open it, count, press it down. Then wind on.', 'ISO 400 film. Sun: open and shut. Cloud: count 1. Shade: 3. Indoors by a window: 40.', 'Nothing on the film: count longer next time.', 'The pinhole lets in about 150 times less light than the large dot, so a picture is counted, not snapped. It is sharp at every distance, and a little soft everywhere.'),
]
for st, short in zip(WEB, ("From the bag, or made: an adult cuts a 10 mm square from a clean can with kitchen scissors and snips off its corners. Dent its middle with a pin, push just through, check it against a lamp.",
                          "Lens out. Lay the disc flat in the lens pocket, hole in the middle. Press the pinhole ring in on top until it stops.",
                          "Large dot. Stand the camera still. Hold the rocker level, count, press it down. ISO 400: sun, open and shut; cloud 1; shade 3; indoors 40.")): st["short"] = short     # the printed guide's page has room for less
CODE = {"BUILD": "b", "THE HOLE": "h", "FILM IN": "f", "PHOTOS": "p", "FILM OUT": "o"}
def code(st): return CODE[st["sec"]] + str(st["n"])        # b7, f2, h3: the clip's file name and the page's address
PARTS = [("front", "front plate", "holds the lens, the shutter and the wheel; slides onto the body"), ("blade", "shutter", "swings across to let light in for an instant; the rocker on top is its button"), ("wheel", "aperture wheel", "three holes: how much light"),
         ("body", "body", "the dark box; the film lies on its curved rails"), ("spool", "spool", "the film is wound onto it first; its knob is the big red one"),
         ("knob", "wind knob", "the small green knob; winds each picture back into the film's shell"), ("roller", "frame wheel", "turned by the film; the arrow on its blue dial goes round once for each picture"), ("back", "back", "closes the box; carries the frame wheel and the post the film turns round")]
TROUBLE = [("The plate will not slide", "It is not flat on the body: the rocker's arm or the handle is not through its opening, or the feet are not in their pockets", "Lift off, look, set it on again a little high and to one side"), ("The front plate stands high, or has come off", "A knock or a fall", "Set it on, slide it sideways until it stops, then down until it clicks"), ("The rocker does not click", "The print is too loose", "Ask whoever printed the kit to run the fit gauge"),
           ("The back will not close", "The frame wheel is not slid home, a knob is not fully in, or the film's tip is in the way", "Open, look, close"), ("The small green knob is stiff", "A hand is on the big red knob, or the film is at its end", "Stop. Never force it"),
           ("The arrow on the dial does not move while winding", "The film did not catch in the spool", "Open in the shade, tuck the tip in deeper"), ("Winding is heavy all the way", "The film rubs round the post on the back; a rough print makes it worse", "Rub the rounded top of the post smooth with a fingernail"), ("Pictures are blank", "The film did not move (see above), or the rocker was never pressed right down", "Check both on the next roll"),
           ("Two pictures on top of each other", "The film was not wound on between them", "Press the rocker, then wind, every time"), ("Streaks or fog", "The back was opened with film inside, or the plastic lets light through", "Keep the back shut; print in black"),
           ("The rocker has snapped off", "A knock from the front or the back", "Fit the spare shutter: push the front plate up past its click, slide it sideways, lift it off, swap, put it back")]
